import React, { useState, useEffect } from 'react';

function TestApp() {
  const [error, setError] = useState(null);
  const [loaded, setLoaded] = useState(false);

  useEffect(() => {
    try {
      // Simulate checking for errors
      console.log('TestApp component mounted');
      setLoaded(true);
    } catch (err) {
      console.error('Error in TestApp:', err);
      setError(err.message);
    }
  }, []);

  if (error) {
    return (
      <div style={{
        textAlign: 'center',
        marginTop: '100px',
        fontFamily: 'Arial, sans-serif',
        color: 'red',
        padding: '20px',
        border: '1px solid red',
        borderRadius: '8px',
        maxWidth: '600px',
        margin: '100px auto'
      }}>
        <h1>Error Occurred</h1>
        <p>{error}</p>
      </div>
    );
  }

  return (
    <div style={{
      textAlign: 'center',
      marginTop: '100px',
      fontFamily: 'Arial, sans-serif',
      padding: '20px',
      border: '1px solid #ccc',
      borderRadius: '8px',
      maxWidth: '600px',
      margin: '100px auto',
      backgroundColor: '#f9f9f9'
    }}>
      <h1>React Test Page</h1>
      <p>If you can see this, React is working correctly!</p>
      <p>Loaded: {loaded ? 'Yes' : 'No'}</p>
      <button
        style={{
          padding: '10px 20px',
          backgroundColor: '#4CAF50',
          color: 'white',
          border: 'none',
          borderRadius: '4px',
          cursor: 'pointer',
          marginTop: '20px'
        }}
        onClick={() => alert('Button clicked!')}
      >
        Click Me
      </button>
    </div>
  );
}

export default TestApp;
